<script setup>
import {ref,computed,onMounted,watch} from 'vue';
import {House,Users,Clock3,BookOpen,Library,Wallet,Activity,ScrollText,LogOut,ArrowUpRight,ArrowLeft,Search,Download,RefreshCw,Menu,X,ChevronLeft,ChevronRight,Play,ShieldCheck,ArrowRight,Check,AlertCircle} from 'lucide-vue-next';
const nav=[['overview','总览',House,'OVERVIEW'],['users','用户管理',Users,'LEARNERS'],['daily','使用时长',Clock3,'DAILY ACTIVITY'],['events','学习记录',Activity,'LEARNING'],['courses','课程查看',BookOpen,'CURRICULUM'],['lexicon','词汇与素材',Library,'LIBRARY'],['billing','腾讯云费用',Wallet,'BILLING'],['system','系统状态',ShieldCheck,'SYSTEM'],['logs','操作记录',ScrollText,'ACTIVITY LOG']];
const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const route=ref(location.hash.slice(1)||'overview'),user=ref(null),boot=ref(true),busy=ref(false),error=ref(''),toast=ref(''),mobile=ref(false),username=ref('admin'),password=ref('');
const sort=ref('default');
const from=ref(today),to=ref(today),month=ref(today.slice(0,7)),query=ref(''),page=ref(1),data=ref({}),catalog=ref({courses:[],lexicon:[]}),selected=ref(null),userDetail=ref(null),status=ref('all'),confirmAction=ref(null),preview=ref(false),requestId=ref(0);
const active=computed(()=>nav.find(n=>n[0]===route.value)||nav[0]);
const rows=computed(()=>data.value.rows||[]),money=n=>Number(n||0).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:6});
const duration=n=>{n=Math.floor((n||0)/1000);return n>=3600?`${Math.floor(n/3600)} 小时 ${Math.floor(n%3600/60)} 分`:`${Math.floor(n/60)} 分 ${n%60} 秒`;};
const time=n=>n?new Date(n).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'暂无记录';
const published=computed(()=>catalog.value.courses.filter(c=>c.status==='published').length);
const courseName=id=>catalog.value.courses.find(c=>c.id===id)?.title||id;
const types={start:'开始课程',stage:'进入阶段',pass:'可靠通过',correct:'需纠正',uncertain:'未可靠识别',help:'听取提示',skip:'跳过',pause:'暂停',finish:'到达结尾',expose:'词汇接触'};
async function api(path,body){const response=await fetch('/api/admin/'+path,{credentials:'same-origin',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});const value=await response.json();if(!response.ok){if(response.status===401)user.value=null;throw Error(value.error||'请求失败');}return value;}
function go(id){location.hash=id;route.value=id;mobile.value=false;selected.value=null;userDetail.value=null;preview.value=false;query.value='';page.value=1;}
window.addEventListener('hashchange',()=>{const r=location.hash.slice(1);if(nav.some(n=>n[0]===r))route.value=r;});
async function login(){error.value='';busy.value=true;try{const r=await api('login',{username:username.value,password:password.value});user.value=r.user;password.value='';await init();}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function logout(){try{await api('logout',{});user.value=null;data.value={};}catch(e){error.value=e.message;}}
async function init(){catalog.value=await api('catalog');await load();}
async function load(){if(!user.value)return;const id=++requestId.value;busy.value=true;error.value='';const r=route.value;
 try{let result={};if(!['courses','lexicon'].includes(r)){const params=new URLSearchParams({from:from.value,to:to.value,month:month.value,q:query.value,page:page.value,sort:sort.value});result=await api(r+'?'+params);}
 if(id===requestId.value)data.value=result;
 }catch(e){if(id===requestId.value)error.value=e.message;}finally{if(id===requestId.value)busy.value=false;}}
watch(route,()=>{data.value={};load();});
const filteredCourses=computed(()=>catalog.value.courses.filter(c=>(status.value==='all'||c.status===status.value)&&JSON.stringify(c).toLowerCase().includes(query.value.toLowerCase())));
const words=computed(()=>catalog.value.lexicon.filter(w=>JSON.stringify(w).toLowerCase().includes(query.value.toLowerCase())));
const trend=computed(()=>{const values=new Map();for(const d of data.value.trend||[])values.set(d.date,(values.get(d.date)||0)+d.learningMs);const a=[];for(let i=6;i>=0;i--){const day=new Date(Date.parse(to.value+'T00:00:00Z')-i*86400000).toISOString().slice(0,10);a.push({day,value:values.get(day)||0});}return a;});
const maxTrend=computed(()=>Math.max(1,...trend.value.map(d=>d.value)));
const billProducts=computed(()=>data.value.data?.summary?.SummaryOverview||[]);
const billDetails=computed(()=>(data.value.data?.details||[]).filter(r=>!query.value||JSON.stringify(r).toLowerCase().includes(query.value.toLowerCase())));
async function openUser(u){busy.value=true;try{userDetail.value=await api('users/'+u.id+'?'+new URLSearchParams({from:from.value,to:to.value}));}catch(e){error.value=e.message;}finally{busy.value=false;}}
async function action(){try{await api('users/'+confirmAction.value.id,{action:confirmAction.value.action});confirmAction.value=null;userDetail.value=null;await load();notify('操作已完成');}catch(e){error.value=e.message;}}
async function refreshBill(){busy.value=true;error.value='';try{await api('billing?month='+month.value,{});await load();notify('腾讯账单同步完成');}catch(e){const message=e.message;await load();error.value=message;}finally{busy.value=false;}}
function notify(t){toast.value=t;setTimeout(()=>toast.value='',3500);}
async function exportRows(){try{const result=await api(route.value+'?'+new URLSearchParams({from:from.value,to:to.value,q:query.value,sort:sort.value,export:'1'}));const items=result.rows;if(!items.length){notify('当前筛选没有可导出的记录');return;}const keys=Object.keys(items[0]);const escape=v=>'"'+String(typeof v==='object'?JSON.stringify(v):v??'').replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv='\ufeff'+[keys,...items.map(r=>keys.map(k=>r[k]))].map(r=>r.map(escape).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`${route.value}-${from.value}-${to.value}.csv`;a.click();URL.revokeObjectURL(url);}catch(e){error.value=e.message;}}
function changePage(delta){page.value+=delta;load();}
onMounted(async()=>{try{user.value=(await api('me')).user;await init();}catch{}finally{boot.value=false;}});
</script>

<template>
 <div v-if="boot" class="boot">SNOW SPEAKS <span>正在连接管理中心…</span></div>
 <main v-else-if="!user" class="login-screen">
  <section class="login-art"><a class="wordmark" href="/scene/">S<span>●</span> / SNOW SPEAKS</a><div><p class="eyebrow">A LITTLE EVERY DAY.</p><h1>让每一次开口，<br>都有迹可循<span>。</span></h1><p>课程、学习与成长，在这里一目了然。</p></div><div class="login-tiles"><div class="coral"><BookOpen :size="30"/><strong>从单词<br>到真实表达</strong><span>WORD → PHRASE → SENTENCE</span></div><div class="lavender"><span class="big-eight">08<small>节</small></span><span>已上线的成人课程</span></div><div class="mint"><Activity/><strong>看见每一天<br>的小小进步</strong></div></div><footer>SNOW SPEAKS / MANAGEMENT CONSOLE</footer></section>
  <section class="login-form"><span class="pill"><ShieldCheck :size="15"/> 管理员专属入口</span><h2>欢迎回来<span>↗</span></h2><p>登录后，查看你的教学世界。</p><form @submit.prevent="login"><label>管理员账号<input v-model="username" autocomplete="username" required placeholder="请输入账号" maxlength="40"></label><label>登录密码<input v-model="password" type="password" autocomplete="current-password" required placeholder="请输入密码" maxlength="200"></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="busy">{{busy?'正在登录…':'进入管理中心'}}<ArrowRight :size="20"/></button></form><small>课程由助手持续制作更新 · 腾讯费用来自官方账单</small></section>
 </main>
 <div v-else class="shell">
  <button class="mobile-shade" v-if="mobile" aria-label="关闭导航" @click="mobile=false"></button>
  <aside :class="['rail',{expanded:mobile}]"><button class="logo" aria-label="管理总览" @click="go('overview')">S<span>●</span></button><nav><button v-for="(item,i) in nav" :key="item[0]" :class="['nav-item',{active:route===item[0],separator:i===4||i===6}]" @click="go(item[0])" :aria-label="item[1]" :aria-current="route===item[0]?'page':undefined"><component :is="item[2]" :size="21"/><span class="nav-label">{{item[1]}}</span><span class="tooltip">{{item[1]}}</span></button></nav><button class="nav-item logout" aria-label="退出登录" @click="logout"><LogOut :size="20"/><span class="nav-label">退出登录</span><span class="tooltip">退出登录</span></button><div class="avatar" title="管理员">AD</div></aside>
  <div class="workspace"><header class="topbar"><button class="mobile-menu icon-button" @click="mobile=!mobile" aria-label="展开导航"><Menu/></button><div class="breadcrumb">工作空间 <span>/</span> <b>{{active[1]}}</b></div><div class="top-actions"><a href="/scene/" target="_blank" rel="noopener" class="quiet-link">进入课堂 <ArrowUpRight :size="16"/></a><span class="account"><span class="dot"></span> admin</span></div></header>
   <main class="content"><div class="page-heading"><div><p class="eyebrow">{{active[3]}} / SNOW SPEAKS</p><h1>{{active[1]}}<span class="heading-dot">.</span></h1><p>{{({overview:'把每天的小进步，汇成看得见的成长。',users:'了解每一位学习者，陪伴每一次进步。',daily:'每一天，花了多久，又学了多久。',events:'从一次开口，到一段完整表达。',courses:'从单词到短语，再到真实生活中的句子。',lexicon:'每个声音、每张图片，都有清晰的教学位置。',billing:'直接读取腾讯云官方账单，费用清楚可查。',system:'让课堂稳定运行，让数据妥善保存。',logs:'每一次重要操作，都有记录可循。'})[route]}}</p></div><span class="date-stamp">{{today.replaceAll('-',' / ')}}<small>北京时间 · UTC+8</small></span></div>
   <div class="toolbar" v-if="['overview','users','daily','events'].includes(route)"><label>从<input aria-label="开始日期" type="date" v-model="from"></label><label>至<input aria-label="结束日期" type="date" v-model="to"></label><button @click="page=1;load()" :disabled="busy">查询</button><div class="search" v-if="route!=='overview'"><Search :size="17"/><input v-model="query" @keyup.enter="page=1;load()" placeholder="搜索用户或记录" aria-label="搜索记录"></div><select v-if="['users','daily'].includes(route)" v-model="sort" aria-label="记录排序" @change="page=1;load()"><option value="default">默认顺序</option><option value="learning">学习时长最多</option><option value="foreground">使用时长最多</option></select><button class="outline" v-if="route!=='overview'" @click="exportRows"><Download :size="16"/>导出</button></div>
   <div class="notice error" v-if="error" role="alert"><AlertCircle :size="18"/>{{error}}<button @click="load">重试</button></div>
   <p class="loading" v-if="busy" role="status">正在读取数据…</p>
   <template v-if="route==='overview'">
    <div class="dashboard"><section class="card coral hero-card"><div class="card-head"><h2><Clock3 :size="22"/> 学习的每一分钟</h2><button class="circle" aria-label="查看使用时长" @click="go('daily')"><ArrowUpRight :size="18"/></button></div><div class="hero-numbers"><div><span>有效学习时长</span><strong>{{duration(data.learningMs)}}</strong></div><div><span>前台使用时长</span><b>{{duration(data.foregroundMs)}}</b></div></div><div class="bar-chart"><div v-for="d in trend" :key="d.day" class="bar-column"><span class="bar-value">{{Math.round(d.value/60000)}}分</span><div class="bar-track"><div :style="{height:(d.value/maxTrend*100)+'%'}"></div></div><span>{{d.day.slice(5)}}</span></div></div><p class="card-foot">截至结束日期的近 7 天 · 仅展示所选范围内已上报数据</p></section>
    <section class="card lavender learners-card"><div class="card-head"><h2>一起学习的人</h2><button class="circle" aria-label="查看用户" @click="go('users')"><ArrowUpRight :size="18"/></button></div><div class="big-metric">{{data.users||0}}<small>位用户</small></div><div class="split-metrics"><div><b>{{data.activeUsers||0}}</b><span>期间使用人数</span></div><div><b>{{data.newUsers||0}}</b><span>期间新增用户</span></div></div></section>
    <section class="card dark progress-card"><div class="card-head"><h2>一次开口，一步向前</h2><Activity :size="20"/></div><div class="split-metrics"><div><b>{{data.starts||0}}</b><span>开始课程</span></div><div><b>{{data.finishes||0}}</b><span>到达结尾</span></div><div><b>{{data.eventCount||0}}</b><span>学习事件</span></div></div><p>到达结尾不等于全部掌握，提示与跳过分别记录。</p><button class="text-button" @click="go('events')">查看学习记录 <ArrowRight :size="16"/></button></section>
    <section class="card cyan course-card" @click="go('courses')"><div class="card-head"><h2>课程地图</h2><ArrowUpRight/></div><strong class="display-number">{{String(published).padStart(2,'0')}}<span>/ {{catalog.courses.length}}</span></strong><div class="unit-blocks"><span v-for="i in 16" :class="{done:i<=8}" :key="i"></span></div><p>{{Math.ceil(published/4)}} 个单元已上线 · 后续课程持续制作</p><button class="text-button">浏览全部课程 <ArrowRight :size="16"/></button></section>
    <section class="card mint data-card"><div class="card-head"><h2>真实记录</h2><ShieldCheck/></div><div class="data-illustration"><Clock3 :size="66" :stroke-width="1"/><span>DAY BY DAY</span></div><p>采集开始于 {{time(data.started)}}。<br>历史未采集的学习时长不补算。</p></section>
    <section class="card dark next-card"><span class="pill yellow">运营提示</span><h2>内容交给助手，<br>进步在这里看见。</h2><p>课程内容支持完整预览。费用直接查看腾讯云账单，不做本地估算。</p><div class="button-row"><button @click="go('courses')">查看课程</button><button class="outline" @click="go('billing')">查看费用 <ArrowUpRight :size="14"/></button></div></section></div>
   </template>
   <template v-if="['users','daily','events','logs'].includes(route)">
    <section v-if="userDetail" class="card detail-panel"><button class="text-button" @click="userDetail=null"><ArrowLeft :size="16"/>返回列表</button><div class="detail-title"><div><h2>{{userDetail.user.nickname}}</h2><p>{{userDetail.user.phoneMasked}} · {{userDetail.user.id}}</p></div><span class="pill">{{userDetail.user.blocked?'已停用':'正常'}}</span></div><div class="button-row"><button @click="confirmAction={id:userDetail.user.id,action:userDetail.user.blocked?'enable':'disable',name:userDetail.user.nickname}">{{userDetail.user.blocked?'恢复账号':'停用账号'}}</button><button class="outline" @click="confirmAction={id:userDetail.user.id,action:'revoke',name:userDetail.user.nickname}">撤销登录会话</button></div><h3>课程进度</h3><div v-for="c in userDetail.checkpoints" :key="c.course" class="record-line"><b>{{courseName(c.course)}}</b><span>{{c.payload.checkpoint?.stageId||'已同步断点'}}</span><small>{{time(c.updated)}}</small></div><p v-if="!userDetail.checkpoints.length" class="empty-small">暂无云端课程进度</p><h3>每日使用</h3><div class="record-line" v-for="d in userDetail.daily" :key="d.date"><b>{{d.date}}</b><span>使用 {{duration(d.foregroundMs)}}</span><span>学习 {{duration(d.learningMs)}}</span></div><p v-if="!userDetail.daily.length" class="empty-small">所选日期暂无已上报记录</p><h3>活动时间线 <small>最近 500 段</small></h3><div class="timeline"><div v-for="(r,i) in userDetail.intervals" :key="i"><span :class="['timeline-dot',{learning:r.active}]"></span><b>{{time(r.start)}}</b><span>{{duration(r.end-r.start)}} · {{r.active?'有效学习':'前台使用'}} · {{courseName(r.course)||'浏览'}}</span></div></div></section>
    <section v-else class="table-panel"><div class="table-caption"><h2>{{active[1]}}</h2><span>共 {{data.total||0}} 条</span></div><div class="table-scroll"><table v-if="rows.length"><thead><tr v-if="route==='users'"><th>学习者</th><th>注册时间</th><th>前台使用</th><th>有效学习</th><th>最近活动</th><th>状态</th><th></th></tr><tr v-if="route==='daily'"><th>日期</th><th>学习者</th><th>前台使用</th><th>有效学习</th><th>会话 / 课程</th><th>练习结果数</th></tr><tr v-if="route==='events'"><th>时间</th><th>学习者</th><th>课程</th><th>阶段</th><th>行为</th></tr><tr v-if="route==='logs'"><th>时间</th><th>操作者</th><th>操作</th><th>对象</th><th>结果</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="r.id||i"><template v-if="route==='users'"><td><b>{{r.nickname}}</b><small>{{r.phoneMasked}}</small></td><td>{{time(r.created)}}</td><td>{{duration(r.foregroundMs)}}</td><td>{{duration(r.learningMs)}}</td><td>{{time(r.last)}}</td><td><span :class="['badge',{muted:r.blocked}]">{{r.blocked?'已停用':'正常'}}</span></td><td><button class="text-button" @click="openUser(r)">详情 <ArrowUpRight :size="16"/></button></td></template><template v-if="route==='daily'"><td>{{r.date}}</td><td>{{r.nickname}}<small>{{r.phoneMasked}}</small></td><td>{{duration(r.foregroundMs)}}</td><td>{{duration(r.learningMs)}}</td><td>{{r.sessions}} / {{r.courses}}</td><td>{{r.attempts}}</td></template><template v-if="route==='events'"><td>{{time(r.at)}}</td><td>{{r.nickname}}</td><td>{{courseName(r.course)}}</td><td>{{r.stage}}</td><td><span class="badge muted">{{types[r.type]||r.type}}</span></td></template><template v-if="route==='logs'"><td>{{time(r.at)}}</td><td>{{r.actor}}</td><td>{{r.action}}</td><td>{{r.target||'—'}}</td><td>{{r.result}}</td></template></tr></tbody></table><div v-else class="empty"><component :is="active[2]" :size="38" :stroke-width="1.3"/><h3>这里还没有记录</h3><p>真实数据将在采集并同步后显示，不补造历史记录。</p></div></div><div class="pagination"><span>第 {{page}} 页 · 每页 30 条</span><button :disabled="page===1" @click="changePage(-1)" aria-label="上一页"><ChevronLeft :size="18"/></button><button :disabled="page*30>=(data.total||0)" @click="changePage(1)" aria-label="下一页"><ChevronRight :size="18"/></button></div></section>
   </template>
   <template v-if="route==='courses'"><div class="toolbar"><div class="search"><Search :size="17"/><input v-model="query" placeholder="搜索课程、单词或句子" aria-label="搜索课程"></div><select v-model="status" aria-label="课程状态"><option value="all">全部状态</option><option value="published">已发布</option><option value="planned">规划中</option></select><span class="subtle">内容由助手持续制作更新</span></div>
    <section v-if="selected" class="card detail-panel"><button class="text-button" @click="selected=null;preview=false"><ArrowLeft :size="16"/>全部课程</button><div class="detail-title"><div><p class="eyebrow">UNIT {{selected.unit}} / {{selected.version||'PLANNED'}}</p><h2>{{selected.title}}</h2><p>{{selected.goal}}</p></div><button v-if="selected.status==='published'" @click="preview=!preview"><Play :size="16"/>{{preview?'关闭课堂预览':'课堂预览'}}</button></div><iframe v-if="preview" :src="'/scene/?adminPreview=1&course='+encodeURIComponent(selected.id)" title="课程真实预览" allow="microphone" class="preview-frame"></iframe><p v-if="preview" class="notice">预览独立于学员统计。人物加载后点击进入；跟读需主动授权麦克风。</p><div class="stages"><article v-for="(s,i) in selected.stages" :key="s.id" class="stage"><div class="stage-number">{{String(i+1).padStart(2,'0')}}</div><div class="stage-body"><span class="stage-phase">{{s.phase}} · {{s.id}}</span><h3>{{s.display||s.speechText||s.chapter}}</h3><p>{{s.text}}</p><p v-if="s.speechText" class="target">跟读目标：{{s.speechText}}</p><span v-if="s.hideAnswer" class="badge">隐藏英文回忆</span><div v-if="s.segments?.length" class="chips"><span v-for="(seg,j) in s.segments" :key="j">{{seg.text||seg.label||seg}}</span></div><audio v-if="s.audio?.url" :src="s.audio.url" controls preload="none"></audio></div><img v-if="s.image" :src="s.image" :alt="s.text||s.display" class="stage-image" @error="$event.target.style.display='none'"></article></div><div v-if="!selected.stages.length" class="empty"><BookOpen/><h3>课程已纳入规划</h3><p>尚未生成教学内容，完成后会在这里更新。</p></div></section>
    <div v-else class="course-grid"><button v-for="(c,i) in filteredCourses" :key="c.id" :class="['course-tile',{planned:c.status==='planned'}]" @click="selected=c"><div :class="['course-cover',['coral','mint','cyan','lavender'][Math.floor(i/4)%4]]"><span>UNIT {{String(c.unit).padStart(2,'0')}}</span><strong>{{c.title.slice(0,2)}}</strong><ArrowUpRight :size="25"/></div><div class="course-info"><span class="badge" :class="{muted:c.status==='planned'}">{{c.status==='published'?'已发布':'规划中'}}</span><h2>{{c.title.slice(5)}}</h2><p>{{c.goal}}</p><footer>{{c.stages.length?c.stages.length+' 个教学阶段':'内容待制作'}}<span>查看详情 →</span></footer></div></button></div>
   </template>
   <template v-if="route==='lexicon'"><div class="toolbar"><div class="search"><Search :size="17"/><input v-model="query" aria-label="搜索词汇" placeholder="搜索英文、中文或课程"></div><span class="subtle">{{words.length}} 个词条 · 词形单独教学，接触词量归原词计数</span></div><details class="phoneme-panel"><summary>独立音素参考录音 · 点击展开</summary><div class="word-grid"><article v-for="p in catalog.phonemes||[]" :key="p.symbol" class="card"><h3>/{{p.symbol}}/</h3><audio :src="p.url" controls preload="none"></audio></article></div><p class="subtle">参考录音来源与授权随课程素材保存，非单词截取。</p></details><div class="word-grid"><article v-for="w in words" :key="w.word" class="card word-card"><h2>{{w.word}}</h2><span class="ipa">{{w.ipa}}</span><p>{{w.meaning}}</p><audio v-if="w.audio?.url" :src="w.audio.url" controls preload="none"></audio><div class="chips"><span v-for="c in w.courses" :key="c">{{c}}</span></div></article></div></template>
   <template v-if="route==='billing'"><div class="toolbar"><label>账单月份<input v-model="month" type="month" aria-label="账单月份" @change="load"></label><button :disabled="busy" @click="refreshBill"><RefreshCw :size="16"/>同步腾讯账单</button><span class="subtle">最近成功同步：{{time(data.updated)}}</span></div><div class="notice" v-if="data.error"><AlertCircle :size="18"/>{{data.error}}</div><div class="billing-banner card lavender"><div><p class="eyebrow">OFFICIAL BILL / {{month}}</p><h2>腾讯云官方费用</h2><p>账号全产品账单 · 可能包含其他项目</p></div><div class="bill-total">{{data.data?'¥ '+money(data.data.summary.SummaryTotal?.RealTotalCost ?? billProducts.reduce((n,r)=>n+Number(r.RealTotalCost||0),0)):'—'}}<small>{{data.data?'官方实际费用合计':'尚未同步官方数据'}}</small></div></div><p class="subtle">汇总通常次日更新，当前月份金额尚未最终出账。套餐支出依腾讯账单呈现；本系统不计算使用成本。</p><div class="table-panel"><div class="table-caption"><h2>产品费用分布</h2></div><div class="table-scroll"><table v-if="billProducts.length"><thead><tr><th>产品</th><th>实际费用</th><th>现金支付</th><th>代金券支付</th></tr></thead><tbody><tr v-for="(p,i) in billProducts" :key="i"><td>{{p.BusinessCodeName}}</td><td>¥ {{money(p.RealTotalCost)}}</td><td>{{p.CashPayAmount==null?'—':'¥ '+money(p.CashPayAmount)}}</td><td>{{p.VoucherPayAmount==null?'—':'¥ '+money(p.VoucherPayAmount)}}</td></tr></tbody></table><div v-else class="empty"><Wallet/><h3>{{data.data?'该月没有费用记录':'等待官方账单同步'}}</h3><p>点击同步读取腾讯费用数据；未接入不视为零费用。</p></div></div></div><div class="table-panel" v-if="billDetails.length"><div class="table-caption"><h2>账单明细</h2><span>{{billDetails.length}} 条</span></div><div class="table-scroll"><table><thead><tr><th>产品 / 子产品</th><th>资源</th><th>计费时间</th><th>计费项与费用</th></tr></thead><tbody><tr v-for="(d,i) in billDetails.slice((page-1)*30,page*30)" :key="i"><td>{{d.BusinessCodeName}}<small>{{d.ProductCodeName}}</small></td><td>{{d.ResourceName||d.ResourceId}}</td><td>{{d.PayTime||d.FeeBeginTime||'—'}}</td><td><div v-for="(c,j) in d.ComponentSet||[]" :key="j">{{c.ComponentCodeName}} · {{c.UsedAmount||''}} {{c.UsedAmountUnit||''}} · ¥ {{money(c.RealCost)}}</div></td></tr></tbody></table></div><div class="pagination"><span>第 {{page}} 页</span><button :disabled="page===1" @click="page--">上一页</button><button :disabled="page*30>=billDetails.length" @click="page++">下一页</button></div></div></template>
   <template v-if="route==='system'"><div class="system-grid"><section class="card mint"><ShieldCheck :size="30"/><h2>应用与课程</h2><h3>{{data.release}}</h3><p>{{data.courseCount}} 节课程已发布</p><p>管理端 Vue 3 · 独立管理员会话</p></section><section class="card dark"><Activity :size="30"/><h2>服务配置</h2><div class="record-line"><span>腾讯语音</span><b>{{data.speechConfigured?'已配置':'未配置'}}</b></div><div class="record-line"><span>短信验证</span><b>{{data.smsReady?'已配置':'尚未开放'}}</b></div><p>配置状态不代表一次实际调用成功。</p></section><section class="card cyan"><Library :size="30"/><h2>数据存储</h2><h3>{{data.database}}</h3><p>采集起始：{{time(data.started)}}</p><p>学习数据与账号在服务端持久化保存。</p></section><section class="card dark"><Clock3 :size="30"/><h2>备份与恢复</h2><p>最近备份：{{time(data.backup)}}</p><p>{{data.backupError||data.backupScope}}</p><p>恢复由受控运维流程执行，避免误覆盖。</p></section></div></template>
   <footer class="page-footer"><span>SNOW SPEAKS <b>管理中心</b></span><span>数据来自真实记录 · 内容持续更新</span></footer>
  </main></div><div v-if="toast" class="toast" role="status"><Check :size="18"/>{{toast}}</div>
  <div v-if="confirmAction" class="modal-backdrop" @click.self="confirmAction=null"><section role="dialog" aria-modal="true" aria-labelledby="confirm-title" class="modal"><button class="close icon-button" @click="confirmAction=null" aria-label="关闭"><X/></button><ShieldCheck :size="32"/><h2 id="confirm-title">确认{{({disable:'停用账号',enable:'恢复账号',revoke:'撤销会话'})[confirmAction.action]}}？</h2><p>操作对象：{{confirmAction.name}}。{{confirmAction.action==='enable'?'用户可以重新登录。':'当前登录会话将被撤销。'}}</p><div class="button-row"><button class="outline" @click="confirmAction=null">取消</button><button @click="action">确认操作</button></div></section></div>
 </div>
</template>
